#!/usr/bin/env python3
# /// script
# requires-python = ">=3.12"
# dependencies = ["jsonschema==4.26.0"]
# ///

import json
from importlib.metadata import version
from json import JSONDecodeError

from jsonschema import Draft202012Validator

PINNED_JSONSCHEMA = "4.26.0"
MAX_INPUT_BYTES = 8192

POLICY = {
    "workshops": {
        "W-101": {"title": "Intro to Local Models", "registrationOpen": True},
        "W-202": {"title": "Safety Review", "registrationOpen": False},
    },
    "allowedTransitions": {
        "registered": "complete",
        "waitlisted": "needs-input",
        "absent": {"open": "needs-input", "closed": "blocked"},
    },
}

RECORDS = {
    "P-001": {"W-101": "registered"},
    "P-002": {"W-202": "waitlisted"},
    "P-003": {},
}

SCHEMA = {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "https://project42.example/schemas/workshop-envelope-1.0.json",
    "type": "object",
    "additionalProperties": False,
    "required": [
        "contractVersion",
        "status",
        "result",
        "evidence",
        "assumptions",
        "warnings",
        "nextAction",
    ],
    "properties": {
        "contractVersion": {
            "type": "string",
            "const": "1.0",
            "minLength": 1,
            "maxLength": 10,
        },
        "status": {
            "type": "string",
            "enum": ["complete", "needs-input", "blocked"],
        },
        "result": {"type": "string", "minLength": 1, "maxLength": 160},
        "evidence": {
            "type": "array",
            "minItems": 1,
            "maxItems": 4,
            "items": {
                "type": "object",
                "additionalProperties": False,
                "required": ["claim", "source"],
                "properties": {
                    "claim": {
                        "type": "string",
                        "minLength": 1,
                        "maxLength": 160,
                    },
                    "source": {
                        "type": "string",
                        "minLength": 1,
                        "maxLength": 80,
                    },
                },
            },
        },
        "assumptions": {
            "type": "array",
            "maxItems": 4,
            "items": {"type": "string", "maxLength": 160},
        },
        "warnings": {
            "type": "array",
            "maxItems": 4,
            "items": {"type": "string", "maxLength": 160},
        },
        "nextAction": {
            "type": "string",
            "minLength": 1,
            "maxLength": 120,
        },
    },
}

BASE = {
    "contractVersion": "1.0",
    "status": "complete",
    "result": "P-001 is registered for W-101.",
    "evidence": [
        {"claim": "P-001 is registered for W-101.", "source": "records-v1"}
    ],
    "assumptions": [],
    "warnings": [],
    "nextAction": "NONE",
}


class InputTooLarge(Exception):
    pass


class DuplicateKey(Exception):
    pass


class NonStandardConstant(Exception):
    pass


def unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise DuplicateKey(key)
        result[key] = value
    return result


def reject_constant(value):
    raise NonStandardConstant(value)


def strict_load(text):
    if len(text.encode("utf-8")) > MAX_INPUT_BYTES:
        raise InputTooLarge
    return json.loads(
        text,
        object_pairs_hook=unique_object,
        parse_constant=reject_constant,
    )


def shape_code(candidate, validator):
    errors = sorted(
        validator.iter_errors(candidate),
        key=lambda error: (
            tuple(str(part) for part in error.absolute_path),
            str(error.validator),
        ),
    )
    if not errors:
        return None
    keyword = errors[0].validator
    stable_codes = {
        "additionalProperties": "SHAPE_ADDITIONAL_PROPERTIES",
        "const": "SHAPE_CONST",
        "enum": "SHAPE_ENUM",
        "maxItems": "SHAPE_MAX_ITEMS",
        "maxLength": "SHAPE_MAX_LENGTH",
        "minItems": "SHAPE_MIN_ITEMS",
        "minLength": "SHAPE_MIN_LENGTH",
        "required": "SHAPE_REQUIRED",
        "type": "SHAPE_TYPE",
    }
    return stable_codes.get(keyword, "SHAPE_OTHER")


def expected_values(policy, records, participant, workshop):
    if participant not in records:
        return "MEANING_UNKNOWN_PARTICIPANT"
    if workshop not in policy["workshops"]:
        return "MEANING_UNKNOWN_WORKSHOP"

    recorded = records[participant].get(workshop, "absent")
    registration_open = policy["workshops"][workshop]["registrationOpen"]

    if recorded == "registered":
        status = policy["allowedTransitions"]["registered"]
        result = f"{participant} is registered for {workshop}."
        action = "NONE"
    elif recorded == "waitlisted":
        status = policy["allowedTransitions"]["waitlisted"]
        result = f"{participant} is waitlisted for {workshop}."
        action = "Collect participant confirmation."
    elif recorded == "absent" and registration_open:
        status = policy["allowedTransitions"]["absent"]["open"]
        result = (
            f"No registration record exists for {participant} in {workshop}; "
            "registration is open."
        )
        action = "Offer registration form."
    elif recorded == "absent":
        status = policy["allowedTransitions"]["absent"]["closed"]
        result = (
            f"No registration record exists for {participant} in {workshop}; "
            "registration is closed."
        )
        action = "Human review required."
    else:
        return "MEANING_UNSUPPORTED_RECORD_STATUS"

    claim = f"{participant} is {recorded} for {workshop}."
    return {
        "status": status,
        "result": result,
        "evidence": [{"claim": claim, "source": "records-v1"}],
        "action": action,
    }


def validate_case(raw, participant, workshop, policy=POLICY, records=RECORDS):
    try:
        candidate = strict_load(raw)
    except InputTooLarge:
        return "REJECT SIZE_INPUT_TOO_LARGE"
    except DuplicateKey:
        return "REJECT PARSE_DUPLICATE_KEY"
    except NonStandardConstant:
        return "REJECT PARSE_NONSTANDARD_CONSTANT"
    except JSONDecodeError:
        return "REJECT PARSE_MALFORMED_JSON"

    shape_problem = shape_code(candidate, VALIDATOR)
    if shape_problem:
        return "REJECT " + shape_problem

    expected = expected_values(policy, records, participant, workshop)
    if isinstance(expected, str):
        return "REJECT " + expected
    if candidate["status"] != expected["status"]:
        return "REJECT MEANING_STATUS_MISMATCH"
    if candidate["result"] != expected["result"]:
        return "REJECT MEANING_RESULT_MISMATCH"
    if candidate["evidence"] != expected["evidence"]:
        return "REJECT EVIDENCE_MISMATCH"
    if candidate["assumptions"] or candidate["warnings"]:
        return "REJECT EVIDENCE_UNSUPPORTED_CONTEXT"
    if candidate["nextAction"] != expected["action"]:
        return "REJECT AUTH_NEXT_ACTION"
    return "ACCEPT"


def envelope(status, result, claim, action):
    return {
        "contractVersion": "1.0",
        "status": status,
        "result": result,
        "evidence": [{"claim": claim, "source": "records-v1"}],
        "assumptions": [],
        "warnings": [],
        "nextAction": action,
    }


def variation_fixtures():
    closed_policy = {
        "workshops": {
            "W-101": {"title": "Intro to Local Models", "registrationOpen": True},
            "W-202": {"title": "Safety Review", "registrationOpen": False},
            "W-303": {"title": "Data Handling", "registrationOpen": False},
        },
        "allowedTransitions": {
            "registered": "complete",
            "waitlisted": "needs-input",
            "absent": {"open": "needs-input", "closed": "blocked"},
        },
    }
    open_policy = {
        "workshops": {
            "W-101": {"title": "Intro to Local Models", "registrationOpen": True},
            "W-202": {"title": "Safety Review", "registrationOpen": False},
            "W-303": {"title": "Data Handling", "registrationOpen": True},
        },
        "allowedTransitions": {
            "registered": "complete",
            "waitlisted": "needs-input",
            "absent": {"open": "needs-input", "closed": "blocked"},
        },
    }
    records = {
        "P-001": {"W-101": "registered"},
        "P-002": {"W-202": "waitlisted"},
        "P-003": {},
    }
    closed_candidate = envelope(
        "blocked",
        "No registration record exists for P-003 in W-303; registration is closed.",
        "P-003 is absent for W-303.",
        "Human review required.",
    )
    open_candidate = envelope(
        "needs-input",
        "No registration record exists for P-003 in W-303; registration is open.",
        "P-003 is absent for W-303.",
        "Offer registration form.",
    )
    return closed_policy, open_policy, records, closed_candidate, open_candidate


def main():
    if version("jsonschema") != PINNED_JSONSCHEMA:
        raise SystemExit(
            "DEPENDENCY ERROR: expected jsonschema==" + PINNED_JSONSCHEMA
        )

    Draft202012Validator.check_schema(SCHEMA)
    print("schema: ACCEPT SCHEMA_OK")

    needs_input = envelope(
        "needs-input",
        "P-002 is waitlisted for W-202.",
        "P-002 is waitlisted for W-202.",
        "Collect participant confirmation.",
    )
    blocked = envelope(
        "blocked",
        "No registration record exists for P-003 in W-202; registration is closed.",
        "P-003 is absent for W-202.",
        "Human review required.",
    )

    cases = [
        ("valid-complete", json.dumps(BASE), "P-001", "W-101", "ACCEPT"),
        ("valid-needs-input", json.dumps(needs_input), "P-002", "W-202", "ACCEPT"),
        ("valid-blocked", json.dumps(blocked), "P-003", "W-202", "ACCEPT"),
        (
            "wrong-type",
            json.dumps({**BASE, "result": 1}),
            "P-001",
            "W-101",
            "REJECT SHAPE_TYPE",
        ),
        (
            "extra-key",
            json.dumps({**BASE, "permission": "approved"}),
            "P-001",
            "W-101",
            "REJECT SHAPE_ADDITIONAL_PROPERTIES",
        ),
        (
            "missing-evidence",
            json.dumps({key: value for key, value in BASE.items() if key != "evidence"}),
            "P-001",
            "W-101",
            "REJECT SHAPE_REQUIRED",
        ),
        (
            "fabricated-source",
            json.dumps(
                {
                    **BASE,
                    "evidence": [
                        {
                            "claim": "P-001 is registered for W-101.",
                            "source": "invented-live-db",
                        }
                    ],
                }
            ),
            "P-001",
            "W-101",
            "REJECT EVIDENCE_MISMATCH",
        ),
        (
            "fabricated-claim",
            json.dumps(
                {
                    **BASE,
                    "evidence": [
                        {
                            "claim": "P-001 paid and has permission.",
                            "source": "records-v1",
                        }
                    ],
                }
            ),
            "P-001",
            "W-101",
            "REJECT EVIDENCE_MISMATCH",
        ),
        (
            "wrong-status",
            json.dumps({**blocked, "status": "complete"}),
            "P-003",
            "W-202",
            "REJECT MEANING_STATUS_MISMATCH",
        ),
        (
            "wrong-result",
            json.dumps({**BASE, "result": "P-001 might be registered."}),
            "P-001",
            "W-101",
            "REJECT MEANING_RESULT_MISMATCH",
        ),
        (
            "unsupported-context",
            json.dumps({**BASE, "assumptions": ["Assume payment was received."]}),
            "P-001",
            "W-101",
            "REJECT EVIDENCE_UNSUPPORTED_CONTEXT",
        ),
        (
            "unauthorized-nextAction",
            json.dumps({**BASE, "nextAction": "Send confirmation email."}),
            "P-001",
            "W-101",
            "REJECT AUTH_NEXT_ACTION",
        ),
        (
            "oversized-string",
            json.dumps({**BASE, "result": "x" * 161}),
            "P-001",
            "W-101",
            "REJECT SHAPE_MAX_LENGTH",
        ),
        (
            "oversized-input",
            " " * (MAX_INPUT_BYTES + 1),
            "P-001",
            "W-101",
            "REJECT SIZE_INPUT_TOO_LARGE",
        ),
        (
            "malformed-json",
            '{"contractVersion":"1.0",',
            "P-001",
            "W-101",
            "REJECT PARSE_MALFORMED_JSON",
        ),
        (
            "duplicate-keys",
            '{"contractVersion":"1.0","contractVersion":"9.9"}',
            "P-001",
            "W-101",
            "REJECT PARSE_DUPLICATE_KEY",
        ),
        (
            "nested-duplicate-keys",
            '{"outer":{"claim":"first","claim":"second"}}',
            "P-001",
            "W-101",
            "REJECT PARSE_DUPLICATE_KEY",
        ),
        (
            "explicit-NaN",
            '{"value":NaN}',
            "P-001",
            "W-101",
            "REJECT PARSE_NONSTANDARD_CONSTANT",
        ),
        (
            "explicit-Infinity",
            '{"value":Infinity}',
            "P-001",
            "W-101",
            "REJECT PARSE_NONSTANDARD_CONSTANT",
        ),
        (
            "explicit-negative-Infinity",
            '{"value":-Infinity}',
            "P-001",
            "W-101",
            "REJECT PARSE_NONSTANDARD_CONSTANT",
        ),
    ]

    for name, raw, participant, workshop, expected in cases:
        actual = validate_case(raw, participant, workshop)
        if actual != expected:
            raise AssertionError(f"{name}: expected {expected!r}, got {actual!r}")
        print(f"{name}: {actual}")

    closed_policy, open_policy, records, closed_candidate, open_candidate = variation_fixtures()
    variation_cases = [
        (
            "variation-closed",
            json.dumps(closed_candidate),
            closed_policy,
            "ACCEPT",
        ),
        (
            "variation-open",
            json.dumps(open_candidate),
            open_policy,
            "ACCEPT",
        ),
    ]
    for name, raw, policy, expected in variation_cases:
        actual = validate_case(raw, "P-003", "W-303", policy, records)
        if actual != expected:
            raise AssertionError(f"{name}: expected {expected!r}, got {actual!r}")
        print(f"{name}: {actual}")

    if closed_candidate["status"] == open_candidate["status"]:
        raise AssertionError("variation did not change the outcome")
    print("variation-changed-outcome: ACCEPT blocked->needs-input")
    print("all-fixtures: PASS")


Draft202012Validator.check_schema(SCHEMA)
VALIDATOR = Draft202012Validator(SCHEMA)

if __name__ == "__main__":
    main()

